/bin/bash -lc "node --input-type=module <<'EOF'
import assert from 'node:assert/strict';
import { createWorkspace } from './src/workspace.js';
import { createDocumentStore } from './src/document-store.js';
for (const action of ['redirect', 'close', 'dispose']) {
  const store = createDocumentStore({ a: 'old', b: 'target', c: 'conflict' });
  const renders = [], handoffs = [];
  const workspace = createWorkspace({ store, renderDocument: value => renders.push(value), onHandoff: (snapshot, navigation) => {
    handoffs.push(snapshot);
    if (action === 'redirect') navigation.open('c');
    if (action === 'close') navigation.close();
    if (action === 'dispose') navigation.dispose();
  }});
  workspace.open('a');
  workspace.edit('edited');
  workspace.open('b');
  assert.deepEqual(handoffs, [{ id: 'a', text: 'edited' }]);
  assert.equal(store.read('a'), 'edited');
  assert.equal(renders.at(-1)?.id ?? null, action === 'redirect' ? 'c' : null);
  workspace.edit('after');
  assert.equal(store.read(action === 'redirect' ? 'c' : 'b'), action === 'redirect' ? 'after' : 'target');
}
console.log('handoff, redirect, close, dispose, and stored text checks passed');
EOF"

